import java.util.*;

public class Main {
    int MOD = 1_000_000_007;

    int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        long total = 0;
        for (int i = 0; i < n; i++) {
            int minVal = arr[i];
            for (int j = i; j < n; j++) {                                            // extend the subarray one element at a time
                minVal = Math.min(minVal, arr[j]);                                      // track the running minimum as the subarray grows
                total = (total + minVal) % MOD;
            }
        }
        return (int) total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] arr = {3, 1, 2, 4};
        System.out.println(solution.sumSubarrayMins(arr));
    }
}

