import java.util.*;

public class Main {
    int MOD = 1_000_000_007;

    int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int[] prevLess = new int[n];
        int[] nextLessEq = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) stack.pop();       // pop everything NOT strictly smaller than arr[i]
            prevLess[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && arr[i] < arr[stack.peek()]) stack.pop();          // pop everything STRICTLY bigger than arr[i] (ties stay, giving <=)
            nextLessEq[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            long left = i - prevLess[i];                                                    // choices for the subarray's LEFT edge
            long right = nextLessEq[i] - i;                                                  // choices for the subarray's RIGHT edge
            total = (total + (long) arr[i] * left * right) % MOD;                            // arr[i] is the minimum in exactly left*right subarrays
        }
        return (int) total;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] arr = {3, 1, 2, 4};
        System.out.println(solution.sumSubarrayMins(arr));
    }
}

